    var insertHyperlinks: Boolean?
    /**
     * Allow inserting rows when worksheet protection is enabled. @default false
     */
    var insertRows: Boolean?
    /**
     * Allow using PivotTables when worksheet protection is enabled. @default false
     */
    var pivotTables: Boolean?
    /**
     * Allow selecting locked cells when worksheet protection is enabled. @default true
     */
    var selectLockedCells: Boolean?
    /**
     * Allow selecting unlocked cells when worksheet protection is enabled. @default true
     */
    var selectUnlockedCells: Boolean?
    /**
     * Optional password required to unprotect the worksheet.
     */
    var password: String?
}

external interface ExcelStyle {
    /**
     * The id of the Excel Style, this should match a CSS cell class.
     */
    var id: String
    /**
     * Use this property to customise cell alignment properties.
     */
    var alignment: ExcelAlignment?
    /**
     * Use this property to customise cell borders.
     */
    var borders: ExcelBorders?
    /**
     * Use this property to specify the type of data being exported.
     */
    var dataType: ExcelDataType?
    /**
     * Use this property to customise the font used in the cell.
     */
    var font: ExcelFont?
    /**
     * Use this property to customise the cell background.
     */
    var interior: ExcelInterior?
    /**
     * Use this property to customise the cell value as a formatted number.
     */
    var numberFormat: ExcelNumberFormat?
    /**
     * Use this property to configure cell locking and formula visibility for the exported
     * worksheet. This must be used together with `ExcelExportParams.protectSheet`.
     */
    var protection: ExcelProtection?
}

external interface ExcelTable {
    var columns: Array<ExcelColumn>
    var rows: Array<ExcelRow>
}

external interface ExcelTableConfig {
    /**
     * This property is used to set the table name. It should be an alphanumeric string with no
     * special characters. @default 'AG-GRID-TABLE'
     */
    var name: String?
    /**
     * Set this property to `false` to disable the filter button at the exported Excel table header.
     * Set it to `true` to show the filter button on all columns. Set it to `match` to show the
     * filter button only if the column has a filter allowed. @default match
     */
    var showFilterButton: BooleanOrString17?
    /**
     * Set this property to `false` to hide the row stripes. @default true
     */
    var showRowStripes: Boolean?
    /**
     * Set this property to `true` to show column stripes. @default false
     */
    var showColumnStripes: Boolean?
    /**
     * Set this property to `true` to show the first column in bold/highlighted style. @default
     * false
     */
    var highlightFirstColumn: Boolean?
    /**
     * Set this property to `true` to show the last column in bold/highlighted style. @default false
     */
    var highlightLastColumn: Boolean?
}

external interface ExcelWorksheet {
    var name: String
    var table: ExcelTable
}

external interface ExcelWorksheetConfigParams {
    /**
     * If set to `true`, this will try to convert any cell that starts with `=` to a formula,
     * instead of setting the cell value as regular string that starts with `=`. @default false
     */
    var autoConvertFormulas: Boolean?
    /**
     * Defines the default column width. If no value is present, each column will have value
     * currently set in the application with a min value of 75px. This property can also be supplied
     * a callback function that returns a number.
     */
    var columnWidth: DoubleOrColumnWidthCallbackParamsDouble2?
    /**
     * The height in pixels of header rows. Defaults to Excel default value. This property can also
     * be supplied a callback function that returns a number.
     */
    var headerRowHeight: DoubleOrRowHeightCallbackParamsDouble3?
    /**
     * The height in pixels of all rows. Defaults to Excel default value. This property can also be
     * supplied a callback function that returns a number.
     */
    var rowHeight: DoubleOrRowHeightCallbackParamsDouble4?
    /**
     * The name of the sheet in Excel where the grid will be exported. Either a string or a function
     * that returns a string can be used. If a function is used, it will be called once before the
     * export starts. There is a max limit of 31 characters per sheet name. @default 'ag-grid'
     */
    var sheetName: StringOrExcelSheetNameGetter2?
    /**
     * If `true`, protects the worksheet to enforce `ExcelStyle.protection` settings. Provide an
     * `ExcelSheetProtection` config object to allow specific actions on the protected sheet.
     * @default false
     */
    var protectSheet: BooleanOrExcelSheetProtection2?
    /**
     * The configuration for header and footers.
     */
    var headerFooterConfig: ExcelHeaderFooterConfig?
    /**
     * The Excel document page margins. Relevant for printing.
     */
    var margins: ExcelSheetMargin?
    /**
     * Allows you to setup the page orientation and size.
     */
    var pageSetup: ExcelSheetPageSetup?
    /**
     * Used to add an Excel table to the spreadsheet. Set to `true` to use default export table
     * config, or provide a config object. @default false
     */
    var exportAsExcelTable: BooleanOrExcelTableConfig2?
    /**
     * The expand/collapse state of each row group in the Excel Document. - expanded: All row groups
     * will be expanded by default. - collapsed: All row groups will be collapsed by default. -
     * match: The row groups will match their current state in the Grid. @default 'expanded'
     */
    var rowGroupExpandState: ExpandedOrCollapsedOrMatch?
    /**
     * If `true`, the outline (controls to expand and collapse) for Row Groups will not be added
     * automatically to the Excel Document. @default false.
     */
    var suppressRowOutline: Boolean?
    /**
     * If `true`, the outline (controls to expand and collapse) for Group Columns will not be added
     * automatically to the Excel Document. @default false.
     */
    var suppressColumnOutline: Boolean?
    /**
     * Use this property to select to freeze rows at the top of the exported sheet. - `headers` -
     * Freeze all grid headers at the top. - `headersAndPinnedRows` - Freeze all headers and pinned
     * top rows. - A callback function that will freeze rows until a value other than `true` is
     * returned, after that, this callback will no longer be executed. Note that using a callback
     * will automatically freeze all header rows.
     */
    var freezeRows: StringOrStringOrExcelFreezeRowsGetter2?
    /**
     * Use this property to select to freeze columns at the start of the grid (this will be the
     * columns at the right for RTL). - `pinned` - Freeze all pinned left (right for RTL grids)
     * columns. - A callback function that will freeze columns until a value other than `true` is
     * returned. After that, this callback will no longer be executed.
     */
    var freezeColumns: StringOrExcelFreezeColumnsGetter2?
    /**
     * Use to set the direction for the worksheet. - `true`: Sets the direction to right-to-left
     * (RTL). - `false`: Sets the direction to left-to-right (LTR). - `undefined`: Exports the
     * worksheet according to the current direction of the grid as set by `gridOptions.enableRtl`.
     * @default undefined
     */
    var rightToLeft: Boolean?
    /**
     * Use to export an image for the gridCell in question.
     */
    var addImageToCell: (Double, Column, String) -> ExcelExportParamsAddImageToCellOptions?
    /**
     * Set to `true` to suppress exporting cell notes from the grid `notesDataSource`.
     * Callback-based note injection via `processNoteCallback` still works when this is set.
     * @default false
     */
    var suppressGridNotesExport: Boolean?
    /**
     * Allows customising, suppressing, or injecting Excel notes/comments for exported cells. Return
     * `undefined` to keep the default behaviour, `null` to suppress the note for the current cell,
     * or an `ExcelNote` to export a custom note.
     */
    var processNoteCallback: (ProcessNoteForExportParams) -> ExcelNote?
}

external interface IExcelCreator {
    fun getDataAsExcel(params: ExcelExportParams?): BlobOrString?
    fun getSheetDataForExcel(params: ExcelExportParams?): String
    fun getMultipleSheetsAsExcel(params: ExcelExportMultipleSheetParams): Blob?
    fun exportDataAsExcel(params: ExcelExportParams?)
    fun exportMultipleSheetsAsExcel(params: ExcelExportMultipleSheetParams)
    /**
     * private methods
     */
    fun setFactoryMode(factoryMode: ExcelFactoryMode)
    fun getFactoryMode(): ExcelFactoryMode
}

/**
 * 继承上游 `ProcessCellForExportParams`。
 */
external interface ProcessNoteForExportParams : ProcessCellForExportParams {
    /**
     * The grid note resolved for the current cell, when the Notes feature is available.
     */
    var gridNote: Note?
    /**
     * The Excel note/comment value derived from `gridNote` when automatic note export is enabled.
